          tags: ['sub-brands', 'umbrella-brands', 'adco-diva', 'feba', 'maxel-magic', 'edita-molto', 'unilever-sunsilk', 'pos-naming-discrepancy', 'air-59'],
          lastUpdated: '2026-10-01',
